func main() {
	var n, m int
	fmt.Scan(&n, &m)
	parent := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Scan(&a, &b)
		ra, rb := root(parent, a), root(parent, b)
		if ra != rb {
			parent[rb] = ra
		}
