	var q int
	fmt.Scan(&q)
	for ; q > 0; q-- {
		var a, b int
		fmt.Scan(&a, &b)
		if root(parent, a) == root(parent, b) {
			fmt.Printf("%d %d: same circle\n", a, b)
		} else {
			fmt.Printf("%d %d: different circles\n", a, b)
		}
	}
}

