func find(parent []int, x int) int {
	if parent[x] != x {
		parent[x] = find(parent, parent[x]) // point x straight at its root
	}
	return parent[x]
}

func main() {
	var n int
	fmt.Scan(&n)
	parent := make([]int, n)
	for i := range parent {
		fmt.Scan(&parent[i])
	}
	fmt.Println("before:", parent)

	var q int
	fmt.Scan(&q)
	for ; q > 0; q-- {
		var x int
		fmt.Scan(&x)
		fmt.Printf("%d: root %d\n", x, find(parent, x))
	}
	fmt.Println("after:", parent)
}

